package com.oms.order.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;

/** Platform facts are persisted independently of business conversion and adopted plans. */
@Service public class RefundService {
    @Resource OrderRepository repository;
    TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    Map<String,Object> platform(String company,long id,boolean locked){List<Map<String,Object>> r=repository.db().query("SELECT * FROM oms_platform_refund WHERE company_code=? AND id=?"+(locked?" FOR UPDATE":""),ROW,company,id);require(r.size()==1,"平台退款不存在或无权访问");return r.get(0);}
    Map<String,Object> business(String company,long id,boolean locked){List<Map<String,Object>> r=repository.db().query("SELECT * FROM oms_refund WHERE company_code=? AND id=?"+(locked?" FOR UPDATE":""),ROW,company,id);require(r.size()==1,"业务退款不存在或无权访问");return r.get(0);}
    void lockOriginal(String company,long channel,String tid){repository.db().query("SELECT id FROM oms_platform_order WHERE company_code=? AND channel_id=? AND platform_tid=? ORDER BY id FOR UPDATE",ROW,company,channel,tid);repository.db().query("SELECT id FROM oms_order WHERE company_code=? AND channel_id=? AND platform_tid=? ORDER BY id FOR UPDATE",ROW,company,channel,tid);}
    void event(String company,long id,String action,String message,String actor){repository.db().update("INSERT INTO oms_refund_event(company_code,refund_id,action,message,actor) VALUES (?,?,?,?,?)",company,id,action,message.substring(0,Math.min(1000,message.length())),actor);if(repository.gifts()!=null){Map<String,Object> b=business(company,id,false);repository.gifts().changed(company,number(b,"order_id"));}}
    Map<String,Object> ingest(String company,long channel,String seller,Map<String,Object> source,String actor){
        String rid=numeric(text(source,"refund_id")),tid=numeric(text(source,"tid")),oid=numeric(text(source,"oid")),raw=text(source,"jdp_response"),digest=hash(raw);require(seller.equals(text(source,"seller_nick")),"推送记录卖家不属于所选店铺");require(raw.length()<=2097152,"平台退款报文超过2MB，请按单核对");time(text(source,"jdp_modified"));List<String> identity=repository.db().queryForList("SELECT platform_tid FROM oms_platform_refund WHERE company_code=? AND channel_id=? AND refund_id=?",String.class,company,channel,rid);lockOriginal(company,channel,identity.isEmpty()?tid:identity.get(0));
        Map<String,Object> parsed=new LinkedHashMap<>();String error="";try{parsed=parse(raw);require(rid.equals(text(parsed,"refund_id"))&&tid.equals(text(parsed,"tid"))&&oid.equals(text(parsed,"oid"))&&seller.equals(text(parsed,"seller_nick")),"平台退款表头与报文身份不一致");}catch(IllegalArgumentException e){error=e instanceof NumberFormatException?"平台退款数量或金额格式无效":e.getMessage();if(error==null)error="平台退款资料无效";error=error.substring(0,Math.min(500,error.length()));}
        List<Map<String,Object>> old=repository.db().query("SELECT * FROM oms_platform_refund WHERE company_code=? AND channel_id=? AND refund_id=? FOR UPDATE",ROW,company,channel,rid);Map<String,Object> before=old.isEmpty()?null:old.get(0);String outcome=error.isEmpty()?"NEW":"INVALID";
        if(before!=null){if(!error.isEmpty())outcome="INVALID";else{int compare=versionCompare(parsed,before);outcome=compare<0?"OLDER":compare==0&&fingerprint(parsed).equals(text(before,"semantic_hash"))?"DUPLICATE":compare==0?"CONFLICT":"UPDATED";}}
        if(before!=null&&"DUPLICATE".equals(outcome)&&"INVALID".equals(text(before,"source_state")))outcome="UPDATED";
        if(before!=null&&(!tid.equals(text(before,"platform_tid"))||!oid.equals(text(before,"platform_oid"))))outcome="CONFLICT";
        long id;if(before==null){id=repository.insert("INSERT INTO oms_platform_refund(company_code,channel_id,refund_id,platform_tid,platform_oid,seller_nick,platform_status,jdp_modified,source_hash,payload,source_state,source_error) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",company,channel,rid,tid,oid,seller,text(source,"status"),source.get("jdp_modified"),digest,raw,error.isEmpty()?"VALID":"INVALID",error);before=platform(company,id,true);}else id=number(before,"id");
        repository.db().update("INSERT IGNORE INTO oms_platform_refund_snapshot(company_code,platform_refund_id,payload_hash,payload,source_modified,jdp_modified,outcome) VALUES (?,?,?,?,?,?,?)",company,id,digest,raw,error.isEmpty()?parsed.get("modified"):source.get("modified"),source.get("jdp_modified"),outcome);
        if(Arrays.asList("NEW","UPDATED").contains(outcome)){
            repository.db().update("UPDATE oms_platform_refund SET platform_tid=?,platform_oid=?,platform_status=?,dispute_type=?,source_phase=?,special_type=?,refund_fee=?,platform_quantity=?,reason=?,source_modified=?,refund_version=?,jdp_modified=?,source_hash=?,semantic_hash=?,payload=?,source_state='VALID',source_error='',version=version+?,last_sync=NOW(),conversion_state=IF(business_refund_id IS NULL,'WAITING',conversion_state) WHERE company_code=? AND id=?",tid,oid,parsed.get("status"),parsed.get("dispute_type"),phase(text(parsed,"refund_phase")),special(parsed),money(parsed.get("refund_fee")),number(parsed,"num"),text(parsed,"reason").substring(0,Math.min(500,text(parsed,"reason").length())),parsed.get("modified"),text(parsed,"refund_version"),source.get("jdp_modified"),digest,fingerprint(parsed),raw,"UPDATED".equals(outcome)?1:0,company,id);
            if(before.get("business_refund_id")!=null){long b=number(before,"business_refund_id");String fund="SUCCESS".equals(text(parsed,"status"))?"SUCCESS":"CLOSED".equals(text(parsed,"status"))?"CLOSED":"NONE";
                Map<String,Object> existing=business(company,b,true);boolean adopted=existing.get("approved_version")!=null;boolean samePlan=adopted&&planFingerprint(parsed).equals(text(existing,"approved_hash"));
                if(adopted&&!samePlan)repository.db().update("UPDATE oms_refund SET review_state='STALE',state='BLOCKED',problem_code='PLATFORM_CHANGED',problem_message='平台申请内容已变化，请核对原方案；已执行事实保留',control_version=control_version+1 WHERE company_code=? AND id=?",company,b);
                else if(samePlan&&"APPROVED".equals(text(existing,"review_state")))repository.db().update("UPDATE oms_refund SET approved_version=(SELECT version FROM oms_platform_refund WHERE company_code=? AND id=?),control_version=control_version+1 WHERE company_code=? AND id=?",company,id,company,b);
                if("NONE".equals(fund)&&"CLOSED".equals(text(existing,"funds_state")))repository.db().update("UPDATE oms_refund SET review_state='STALE',state='BLOCKED',problem_code='PLATFORM_REOPENED',problem_message='平台退款重新进入处理，请重新审核方案' WHERE company_code=? AND id=?",company,b);
                if("CLOSED".equals(fund)&&!"SUCCESS".equals(text(existing,"funds_state"))&&existing.get("cancel_command")==null&&number(existing,"cancelled_quantity")==0&&repository.db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=?",Long.class,company,b)==0){repository.db().update("UPDATE oms_refund SET state='CLOSED',goods_state='CANCELED',review_state='CLOSED',problem_code='',problem_message='' WHERE company_code=? AND id=?",company,b);}
                if(fund!=null)repository.db().update("UPDATE oms_refund SET funds_state=IF(funds_state='SUCCESS',funds_state,?) WHERE company_code=? AND id=?",fund,company,b);
                repository.db().update("UPDATE oms_refund SET state=IF(funds_state='SUCCESS' AND goods_state='DONE' AND review_state='APPROVED','COMPLETED',state) WHERE company_code=? AND id=?",company,b);
                repository.db().update("UPDATE oms_refund_return_plan SET parcel_next_attempt=NOW() WHERE company_code=? AND refund_id=? AND logistics_source<>'MANUAL'",company,b);
                event(company,b,"PLATFORM_UPDATE","平台退款更新已保存；"+(samePlan?"申请内容未变，保留已审核方案":"未覆盖已采用方案")+"；"+outcome,actor);
            }
        }else if(Arrays.asList("INVALID","CONFLICT").contains(outcome)){
            String why="CONFLICT".equals(outcome)?"退款身份或同版本内容冲突，请核对平台详情；保留原关联":error;repository.db().update("UPDATE oms_platform_refund SET source_state=?,source_error=?,conversion_error=?,last_sync=NOW() WHERE company_code=? AND id=?",outcome,why,why,company,id);
            if(before.get("business_refund_id")!=null)repository.db().update("UPDATE oms_refund SET state='BLOCKED',review_state='STALE',problem_code='SOURCE_CONFLICT',problem_message=?,control_version=control_version+1 WHERE company_code=? AND id=?",why,company,before.get("business_refund_id"));
        }else repository.db().update("UPDATE oms_platform_refund SET last_sync=NOW() WHERE company_code=? AND id=?",company,id);
        if(Arrays.asList("NEW","UPDATED","INVALID","CONFLICT").contains(outcome))conversionChanged(company,id,true);RefundGuard.refresh(repository,company,channel,text(before,"platform_tid"));return m("id",id,"outcome",outcome);
    }
    public Map<String,Object> convert(String company,long id,String actor){
        Map<String,Object> hint=platform(company,id,false);return tx().execute(s->{lockOriginal(company,number(hint,"channel_id"),text(hint,"platform_tid"));Map<String,Object> p=platform(company,id,true);if(p.get("business_refund_id")!=null)return m("id",p.get("business_refund_id"),"state","SUCCESS");
            if("VALID".equals(text(p,"source_state"))&&"CLOSED".equals(text(p,"platform_status"))){repository.db().update("UPDATE oms_platform_refund SET conversion_state='SKIPPED',conversion_error='平台申请已关闭，未创建本地执行任务' WHERE company_code=? AND id=?",company,id);return m("state","SKIPPED");}
            String error="";boolean waiting=false;List<Map<String,Object>> orders=repository.db().query("SELECT o.*,p.id original_platform_id FROM oms_order o JOIN oms_platform_order p ON p.company_code=o.company_code AND p.id=o.platform_order_id WHERE o.company_code=? AND o.channel_id=? AND o.platform_tid=? AND o.business_type='SALE' ORDER BY o.id LIMIT 2",ROW,company,p.get("channel_id"),p.get("platform_tid"));
            if(!"VALID".equals(text(p,"source_state")))error="平台报文未通过校验，请先处理来源问题";else if(!Arrays.asList("REFUND","REFUND_AND_RETURN").contains(text(p,"dispute_type")))error="不支持的平台申请类型，请核对";else if(orders.isEmpty()){error="等待原业务订单同步转单后自动关联";waiting=true;}else if(orders.size()!=1)error="未找到唯一原业务订单，请核对原订单";else if(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_line WHERE company_code=? AND order_id=? AND platform_oid=?",Long.class,company,orders.get(0).get("id"),p.get("platform_oid"))==0)error="原平台子单未匹配，请核对原订单";
            if(!error.isEmpty()){repository.db().update("UPDATE oms_platform_refund SET conversion_state=?,conversion_error=? WHERE company_code=? AND id=?",waiting?"WAITING":"FAILED",error,company,id);return m("state",waiting?"WAITING":"FAILED","message",error);}
            if("CLOSED".equals(text(p,"platform_status"))){repository.db().update("UPDATE oms_platform_refund SET conversion_state='SKIPPED',conversion_error='平台申请已关闭，未创建本地执行任务' WHERE company_code=? AND id=?",company,id);return m("state","SKIPPED");}
            Map<String,Object> o=orders.get(0);String sn="TK"+token();long b=repository.insert("INSERT INTO oms_refund(company_code,refund_sn,platform_refund_id,channel_id,refund_id,order_id,order_sn,original_platform_order_id,platform_tid,platform_oid,refund_fee,funds_state) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",company,sn,id,p.get("channel_id"),p.get("refund_id"),o.get("id"),o.get("order_sn"),o.get("original_platform_id"),p.get("platform_tid"),p.get("platform_oid"),p.get("refund_fee"),"SUCCESS".equals(text(p,"platform_status"))?"SUCCESS":"NONE");
            repository.db().update("UPDATE oms_platform_refund SET business_refund_id=?,conversion_state='SUCCESS',conversion_error='' WHERE company_code=? AND id=?",b,company,id);event(company,b,"CONVERT","已从平台退款转单；待审核，不代表同意退款或自动截单",actor);RefundGuard.refresh(repository,company,number(p,"channel_id"),text(p,"platform_tid"));return m("id",b,"refund_sn",sn,"state","SUCCESS");
        });
    }
    void conversionChanged(String company,long id,boolean advance){if(repository.messaging()==null)return;Map<String,Object> row=platform(company,id,true);long version=number(row,"intake_version");if(advance){repository.db().update("UPDATE oms_platform_refund SET intake_version=intake_version+1 WHERE company_code=? AND id=?",company,id);version++;}if(row.get("business_refund_id")!=null)return;
        boolean enabled=number(row,"conversion_requested")==1||repository.db().queryForObject("SELECT COUNT(*) FROM oms_refund_config WHERE company_code=? AND channel_id=? AND auto_convert=1",Long.class,company,row.get("channel_id"))==1;
        if(!enabled||!"VALID".equals(text(row,"source_state"))||(!advance&&!"WAITING".equals(text(row,"conversion_state"))))return;
        if(!repository.db().queryForList("SELECT id FROM oms_message_outbox WHERE company_code=? AND service_code='order' AND message_type='REFUND_CONVERT' AND business_id=? AND business_version=? LIMIT 1",company,String.valueOf(id),version).isEmpty())return;
        repository.messaging().enqueue(company,"REFUND_CONVERT",id,version,text(row,"refund_id"),id+":"+version,0);
    }
    public Map<String,Object> requestConvert(String company,long id,String actor){require(repository.messaging()!=null,"退款消息处理未启用，请检查服务配置");Map<String,Object> hint=platform(company,id,false);return tx().execute(s->{lockOriginal(company,number(hint,"channel_id"),text(hint,"platform_tid"));Map<String,Object> p=platform(company,id,true);if(p.get("business_refund_id")!=null)return m("id",p.get("business_refund_id"),"state","SUCCESS");require("VALID".equals(text(p,"source_state")),"请先核对平台来源异常");List<Map<String,Object>> active=repository.db().queryForList("SELECT event_id FROM oms_message_outbox WHERE company_code=? AND service_code='order' AND message_type='REFUND_CONVERT' AND business_id=? AND business_version=? AND process_state IN ('PENDING','WAITING','PROCESSING') LIMIT 1",company,String.valueOf(id),p.get("intake_version"));if(!active.isEmpty()){repository.db().update("UPDATE oms_platform_refund SET conversion_requested=1 WHERE company_code=? AND id=?",company,id);return m("state","PENDING","message","已在转单队列中，请查看后台处理进度");}repository.db().update("UPDATE oms_platform_refund SET conversion_requested=1,conversion_state='WAITING',conversion_error='' WHERE company_code=? AND id=?",company,id);conversionChanged(company,id,true);return m("state","PENDING","message","已提交退款转单，尚未同意退款或执行货物操作");});}
    void autoConvert(String company,long channel){for(Long id:repository.db().queryForList("SELECT id FROM oms_platform_refund WHERE company_code=? AND channel_id=? AND conversion_state='WAITING' AND source_state='VALID' AND business_refund_id IS NULL AND NOT EXISTS(SELECT 1 FROM oms_message_outbox m WHERE m.company_code=oms_platform_refund.company_code AND m.service_code='order' AND m.message_type='REFUND_CONVERT' AND m.business_id=CAST(oms_platform_refund.id AS CHAR) AND m.business_version=oms_platform_refund.intake_version) ORDER BY id LIMIT 20",Long.class,company,channel))tx().execute(s->{conversionChanged(company,id,false);return null;});}
    public Map<String,Object> platformDetail(String company,long id){Map<String,Object> p=platform(company,id,false);p.remove("payload");repository.messageProgress(company,Collections.singletonList(p),"REFUND_CONVERT");p.put("snapshots",repository.db().query("SELECT id,source_modified,jdp_modified,outcome,create_time FROM oms_platform_refund_snapshot WHERE company_code=? AND platform_refund_id=? ORDER BY id DESC LIMIT 30",ROW,company,id));return p;}
    public Map<String,Object> snapshot(String company,long id,long snapshot){platform(company,id,false);List<Map<String,Object>> rows=repository.db().query("SELECT payload,outcome,source_modified,jdp_modified,create_time FROM oms_platform_refund_snapshot WHERE company_code=? AND platform_refund_id=? AND id=?",ROW,company,id,snapshot);require(rows.size()==1,"来源版本不存在或不属于当前退款");Map<String,Object> row=rows.get(0);return row;}
    public Map<String,Object> platformList(String company,Map<String,String> query){return listing(company,query,true);}
    public Map<String,Object> businessList(String company,Map<String,String> query){return listing(company,query,false);}
    private Map<String,Object> listing(String company,Map<String,String> q,boolean platform){String alias=platform?"p":"b",where=" WHERE "+alias+".company_code=?";List<Object> args=new ArrayList<>();args.add(company);String number=q.getOrDefault("number","").trim();if(!number.isEmpty()){require(number.length()<=64,"单号过长");where+=" AND ("+alias+".refund_id=? OR "+alias+".platform_tid=? OR "+alias+".platform_oid=?"+(platform?"":" OR b.refund_sn=? OR b.order_sn=?")+")";for(int i=0;i<(platform?3:5);i++)args.add(number);}
        String channel=q.getOrDefault("channelId","");if(!channel.isEmpty()){require(channel.matches("[1-9][0-9]{0,18}"),"店铺无效");where+=" AND "+alias+".channel_id=?";args.add(Long.parseLong(channel));}String state=q.getOrDefault("state","");if(!state.isEmpty()){where+=" AND "+alias+"."+(platform?"conversion_state":"state")+"=?";args.add(state);}
        String kind=q.getOrDefault("disputeType","");if(!kind.isEmpty()){require(Arrays.asList("REFUND","REFUND_AND_RETURN").contains(kind),"申请类型无效");where+=" AND "+(platform?"p.dispute_type":"(SELECT pr.dispute_type FROM oms_platform_refund pr WHERE pr.company_code=b.company_code AND pr.id=b.platform_refund_id)")+"=?";args.add(kind);}
        if(platform)where=PlatformDocumentQuery.append(where,args,q,false);
        String table=platform?"oms_platform_refund":"oms_refund";long total=repository.db().queryForObject("SELECT COUNT(*) FROM "+table+" "+alias+where,Long.class,args.toArray());int limit=20,page=1;try{page=Integer.parseInt(q.getOrDefault("pageNum","1"));limit=Math.min(50,size(Integer.parseInt(q.getOrDefault("pageSize","20"))));}catch(Exception e){throw new IllegalArgumentException("分页无效");}args.add(limit);args.add(offset(page,limit));String fields=platform?"p.id,p.channel_id,p.refund_id,p.platform_tid,p.platform_oid,p.platform_status,p.dispute_type,p.source_phase,p.special_type,p.refund_fee,p.reason,p.source_modified,p.jdp_modified,p.source_state,p.source_error,p.conversion_state,p.conversion_error,p.business_refund_id,p.version,p.last_sync":"(SELECT pr.dispute_type FROM oms_platform_refund pr WHERE pr.company_code=b.company_code AND pr.id=b.platform_refund_id) dispute_type,b.id,b.channel_id,b.refund_sn,b.platform_refund_id,b.refund_id,b.order_id,b.order_sn,b.platform_tid,b.platform_oid,b.refund_fee,b.state,b.review_state,b.purpose,b.goods_action,b.goods_state,b.funds_state,b.problem_code,b.problem_message,b.control_version,b.shared_return,b.create_time";
        List<Map<String,Object>> rows=repository.db().query("SELECT "+fields+" FROM "+table+" "+alias+where+" ORDER BY "+alias+".id DESC LIMIT ? OFFSET ?",ROW,args.toArray());
        if(!platform&&!rows.isEmpty()){List<Object> totalsArgs=new ArrayList<>();totalsArgs.add(company);for(Map<String,Object> row:rows)totalsArgs.add(row.get("id"));Map<Long,Map<String,Object>> totals=new HashMap<>();for(Map<String,Object> t:repository.db().query("SELECT refund_id,SUM(quantity) return_quantity,SUM(accepted_quantity) accepted_quantity,SUM(posted_quantity) posted_quantity,SUM(waived_quantity) waived_quantity,SUM(parcel_state='NEED_CHECK') parcel_issues,SUM(parcel_state='WAIT_LOGISTICS') parcel_waiting FROM oms_refund_return_plan WHERE company_code=? AND refund_id IN ("+String.join(",",Collections.nCopies(rows.size(),"?"))+") GROUP BY refund_id",ROW,totalsArgs.toArray()))totals.put(number(t,"refund_id"),t);for(Map<String,Object> row:rows)if(totals.containsKey(number(row,"id")))row.put("return_progress",totals.get(number(row,"id")));}
        if(platform)repository.messageProgress(company,rows,"REFUND_CONVERT");else RefundParcelIssues.decorate(repository,company,rows);return m("rows",rows,"total",total);
    }
}
